/* @generated by scripts/css-split.mjs — run `pnpm css:split` after changing imports. */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const WEB = path.join(ROOT, "apps/web");
const SRC = path.join(WEB, "src");
const APP = path.join(SRC, "app");
const LIBS = path.join(ROOT, "libs/shared/ts/src");
const BASE_CSS = path.join(APP, "styles/base.css");
const HER_CSS = path.join(APP, "styles/heroui.css");
const HEADER = "/* @generated by scripts/css-split.mjs — run `pnpm css:split` after changing imports. */\n";
const ENTRY_NAMES = ["layout.tsx", "page.tsx", "not-found.tsx", "error.tsx", "global-error.tsx", "template.tsx"];
const SHARED_DIRS = ["components/ui", "components/navigation", "components/layouts", "components/shared", "components/seo"].map((p) => path.join(SRC, p));
const EXTS = [".tsx", ".ts", ".jsx", ".js"];

const check = process.argv.includes("--check");
const problems = [];

function walk(dir, out = []) {
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name);
    const stat = fs.statSync(full);
    if (stat.isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

function isUnder(file, dir) {
  const rel = path.relative(dir, file);
  return rel !== "" && !rel.startsWith("..") && !path.isAbsolute(rel);
}

function tryFile(base) {
  if (fs.existsSync(base) && fs.statSync(base).isFile()) return base;
  for (const ext of EXTS) {
    const candidate = base + ext;
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate;
  }
  if (fs.existsSync(base) && fs.statSync(base).isDirectory()) {
    for (const ext of EXTS) {
      const candidate = path.join(base, `index${ext}`);
      if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate;
    }
  }
  return null;
}

function resolve(spec, from) {
  const clean = spec.split("?")[0].split("#")[0];
  let base = null;
  if (clean.startsWith(".")) base = path.resolve(path.dirname(from), clean);
  else if (clean.startsWith("@/")) base = path.join(SRC, clean.slice(2));
  else if (clean.startsWith("@gaia/shared/")) base = path.join(LIBS, clean.slice("@gaia/shared/".length));
  if (!base) return null;
  const file = tryFile(base);
  if (!file) return null;
  if (!EXTS.includes(path.extname(file))) return null;
  return file;
}

const IMPORT_RE = /import\s+(?:type\s+)?(?:[^"'()]*?\s+from\s+)?["']([^"']+)["']|import\s*\(\s*["']([^"']+)["']\s*\)|require\s*\(\s*["']([^"']+)["']\s*\)/g;
const HEROUI_RE = /import\s+(?:type\s+)?\{([^}]+)\}\s+from\s+["']@heroui\/react(?:\/([^"']+))?["']/g;

function importsOf(file) {
  const text = fs.readFileSync(file, "utf8");
  const specs = [];
  for (const match of text.matchAll(IMPORT_RE)) specs.push(match[1] || match[2] || match[3]);
  return specs.filter(Boolean);
}

function herouiOf(file) {
  const text = fs.readFileSync(file, "utf8");
  const names = [];
  for (const match of text.matchAll(HEROUI_RE)) {
    if (/^import\s+type\b/.test(match[0])) continue;
    for (const part of match[1].split(",")) {
      const name = part.trim().split(/\s+as\s+/)[0].trim();
      if (name && !name.startsWith("type ")) names.push(name);
    }
  }
  return names;
}

const graphCache = new Map();
function graph(entry) {
  entry = path.resolve(entry);
  if (graphCache.has(entry)) return graphCache.get(entry);
  const seen = new Set();
  const stack = [entry];
  while (stack.length) {
    const file = path.resolve(stack.pop());
    if (seen.has(file) || !fs.existsSync(file) || !fs.statSync(file).isFile()) continue;
    seen.add(file);
    for (const spec of importsOf(file)) {
      const resolved = resolve(spec, file);
      if (resolved && !seen.has(resolved)) stack.push(resolved);
    }
  }
  graphCache.set(entry, seen);
  return seen;
}

function componentFiles() {
  const text = fs.readFileSync(HER_CSS, "utf8");
  const available = [...text.matchAll(/@heroui\/styles\/components\/([a-z0-9-]+)\.css/g)].map((m) => m[1]);
  const normalized = new Map(available.map((name) => [name.replace(/-/g, ""), name]));
  return normalized;
}

function baseComponents() {
  const text = fs.readFileSync(BASE_CSS, "utf8");
  return new Set([...text.matchAll(/@heroui\/styles\/components\/([a-z0-9-]+)\.css/g)].map((m) => m[1]));
}

const AVAILABLE = componentFiles();
const BASE_COMPONENTS = baseComponents();
const ROOT_LAYOUT = path.join(APP, "layout.tsx");
const BASE_OWNED = new Set(graph(ROOT_LAYOUT));

function cssFor(entry, files, components) {
  // Tailwind 4.3 drops every source when a parent-relative source follows a
  // local one, so emit ancestors first and keep same-directory files last.
  const sources = [...files]
    .map((file) => path.relative(path.dirname(entry), file).replace(/\\/g, "/"))
    .sort((a, b) => {
      const ap = a.startsWith(".."), bp = b.startsWith("..");
      if (ap !== bp) return ap ? -1 : 1;
      return a.localeCompare(b);
    })
    .map((rel) => `@source "${rel}";`);
  const componentImports = components.map((name) => `@import "@heroui/styles/components/${name}.css";`);
  const body = [
    HEADER + "@layer theme, base, openui, components, utilities;",
    '@import "tailwindcss/theme.css" layer(theme);',
    '@import "tailwindcss/utilities.css" layer(utilities) source(none);',
    ...componentImports,
    '@import "@heroui/styles/utilities";',
    '@import "@heroui/styles/variants";',
    '@reference "@heroui/styles/themes/default";',
    '@plugin "tailwindcss-animate";',
    '@theme {',
    '  --font-sans: var(--font-inter), system-ui, sans-serif;',
    '  --font-serif: var(--font-aeonik), system-ui, sans-serif;',
    '  --font-mono: var(--font-geist-mono), ui-monospace, "Cascadia Code", "Source Code Pro", Menlo, Consolas, "DejaVu Sans Mono", monospace;',
    '}',
    ...sources,
    '@custom-variant dark (&:is(.dark *));',
    "",
  ];
  return body.join("\n");
}

// Tailwind 4.3 drops sources past this; chunks are worker-inlined.
const MAX_SOURCES = 100;
const FORCE_CHUNKS = new Map();

function chunkSources(sources, minimum = 1) {
  const sorted = [...sources].sort();
  if (sorted.length <= MAX_SOURCES && minimum <= 1) return [sorted];
  const count = Math.max(minimum, Math.ceil(sorted.length / MAX_SOURCES));
  const size = Math.ceil(sorted.length / count);
  const chunks = [];
  for (let i = 0; i < sorted.length; i += size) chunks.push(sorted.slice(i, i + size));
  return chunks;
}

function ancestorsOf(entry) {
  const layouts = [];
  let dir = path.dirname(entry);
  while (isUnder(dir, APP)) {
    const layout = path.join(dir, "layout.tsx");
    if (fs.existsSync(layout) && layout !== ROOT_LAYOUT) layouts.push(layout);
    if (dir === APP) break;
    dir = path.dirname(dir);
  }
  return layouts;
}

function ensureImports(text, cssNames) {
  const cleaned = text.replace(/^import\s+["']\.\/[^"']+\.css["'];\n?/gm, "");
  const lines = cssNames.map((name) => `import "./${name}";\n`).join("");
  const directive = /^((?:\s|\/\/[^\n]*\n|\/\*[\s\S]*?\*\/\n)*)(["'])use (?:client|server)\2;?\n/.exec(cleaned);
  if (directive) {
    const end = directive[0].length;
    return cleaned.slice(0, end) + lines + cleaned.slice(end);
  }
  return lines + cleaned;
}

const entries = walk(APP).filter((file) => ENTRY_NAMES.includes(path.basename(file)) && path.basename(file) !== "layout.tsx" && file !== ROOT_LAYOUT);
const desiredCss = new Map();
const desiredImports = new Map();

for (const entry of entries) {
  const files = graph(entry);
  for (const layout of ancestorsOf(entry)) for (const file of graph(layout)) files.add(path.resolve(file));
  const sources = [...files].filter((file) => !BASE_OWNED.has(path.resolve(file)));

  // Component CSS follows the chunk that first imports it. A component shared by
  // several chunks is still loaded once; CSS is global to the route.
  const componentFiles = new Map();
  for (const file of files) {
    for (const name of herouiOf(file)) {
      const css = AVAILABLE.get(name.toLowerCase().replace(/-/g, ""));
      if (!css || BASE_COMPONENTS.has(css)) continue;
      if (!componentFiles.has(css)) componentFiles.set(css, new Set());
      componentFiles.get(css).add(path.resolve(file));
    }
  }

  const chunks = chunkSources(sources, FORCE_CHUNKS.get(path.relative(ROOT, entry)) ?? 1);
  const chunkSets = chunks.map((chunk) => new Set(chunk));
  const chunkComponents = chunks.map(() => new Set());
  for (const [css, importers] of componentFiles) {
    let index = chunkSets.findIndex((set) => [...importers].some((file) => set.has(file)));
    if (index < 0) index = 0;
    chunkComponents[index].add(css);
  }

  const names = [];
  chunks.forEach((chunk, index) => {
    const components = [...chunkComponents[index]].sort();
    if (chunk.length === 0 && components.length === 0) return;
    const base = path.basename(entry, ".tsx");
    const name = index === 0 ? `${base}.css` : `${base}.${index + 1}.css`;
    desiredCss.set(path.join(path.dirname(entry), name), cssFor(entry, chunk, components));
    names.push(name);
  });
  if (names.length) desiredImports.set(entry, names);
}

for (const [cssPath, content] of desiredCss) {
  const current = fs.existsSync(cssPath) ? fs.readFileSync(cssPath, "utf8") : null;
  if (current === content) continue;
  problems.push(`${path.relative(ROOT, cssPath)}: ${current === null ? "missing" : "out of date"}`);
  if (!check) {
    fs.mkdirSync(path.dirname(cssPath), { recursive: true });
    fs.writeFileSync(cssPath, content);
  }
}

for (const [entry, cssNames] of desiredImports) {
  const text = fs.readFileSync(entry, "utf8");
  const next = ensureImports(text, cssNames);
  if (next === text) continue;
  problems.push(`${path.relative(ROOT, entry)}: missing ${cssNames.map((name) => `"./${name}"`).join(", ")}`);
  if (!check) fs.writeFileSync(entry, next);
}

for (const file of walk(APP)) {
  if (path.basename(file) !== "layout.tsx") continue;
  const text = fs.readFileSync(file, "utf8");
  const next = text.replace(/^import\s+["']\.\/layout\.css["'];\n?/gm, "");
  if (next === text) continue;
  problems.push(`${path.relative(ROOT, file)}: stale local CSS import`);
  if (!check) fs.writeFileSync(file, next);
}

for (const file of walk(APP)) {
  if (!file.endsWith(".css") || path.dirname(file) === path.join(APP, "styles")) continue;
  if (desiredCss.has(file)) continue;
  const text = fs.readFileSync(file, "utf8");
  if (!text.startsWith(HEADER.trim()) && !["home.css", "pricing.css", "marketplace.css"].includes(path.basename(file))) continue;
  problems.push(`${path.relative(ROOT, file)}: stale generated CSS`);
  if (!check) fs.unlinkSync(file);
}

if (problems.length) {
  console.error(`css-split: ${check ? "out of date" : "updated"} (${problems.length})`);
  for (const problem of problems.slice(0, 80)) console.error(`  ${problem}`);
  if (problems.length > 80) console.error(`  ... ${problems.length - 80} more`);
  if (check) process.exit(1);
} else {
  console.log(`css-split: OK (${desiredCss.size} entries)`);
}
